#include "SongWizardPanel.h"
namespace ssbb {
SongWizardPanel::SongWizardPanel(){title_.setText("1. Song Wizard",juce::dontSendNotification);title_.setFont(juce::FontOptions(17.0f,juce::Font::bold));verseLabel_.setText("Verse bars",juce::dontSendNotification);hookLabel_.setText("Hook bars",juce::dontSendNotification);countLabel_.setText("Verses",juce::dontSendNotification);for(auto*s:{&verse_,&hook_,&count_}){s->setSliderStyle(juce::Slider::IncDecButtons);s->setTextBoxStyle(juce::Slider::TextBoxLeft,false,48,22);}verse_.setRange(4,32,4);verse_.setValue(16);hook_.setRange(4,16,4);hook_.setValue(8);count_.setRange(1,8,1);count_.setValue(3);for(auto*c:{static_cast<juce::Component*>(&title_),&verseLabel_,&hookLabel_,&countLabel_,&verse_,&hook_,&count_,&apply_})addAndMakeVisible(c);apply_.onClick=[this]{if(onApply)onApply(static_cast<int>(verse_.getValue()),static_cast<int>(hook_.getValue()),static_cast<int>(count_.getValue()));};}
void SongWizardPanel::paint(juce::Graphics&g){g.setColour(juce::Colour(0xff1b2030));g.fillRoundedRectangle(getLocalBounds().toFloat(),8);}void SongWizardPanel::resized(){auto r=getLocalBounds().reduced(10);title_.setBounds(r.removeFromTop(28));for(auto pair:{std::pair{&verseLabel_,&verse_},std::pair{&hookLabel_,&hook_},std::pair{&countLabel_,&count_}}){auto row=r.removeFromTop(32);pair.first->setBounds(row.removeFromLeft(82));pair.second->setBounds(row);}apply_.setBounds(r.removeFromTop(34).reduced(2));}
} // namespace ssbb
